(function(){
"use strict";
const ROOT="https://fjhululvenojnvhickln.supabase.co";
const KEY="sb_publishable_GbK3GUex9INr7lnigL05Nw_gaAGppHY";
const COLLECTIONS=[["casa-luz","Casa Luz"],["pletora","Plétora"],["eligiendo-milagros","Eligiendo Milagros"],["recursos-generales","Recursos generales"],["logos","Logos"]];
const esc=s=>String(s??"").replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]));
let panel,items=[],collection="casa-luz",busy=false;
function msg(text,error=false){const e=panel?.querySelector("#r2-message");if(e){e.textContent=text;e.className=error?"r2-message error":"r2-message";}}
async function headers(){const s=await window.CFAPI.ensureSession();if(!s?.access_token)throw Error("Inicia sesión de administrador para continuar.");return {apikey:KEY,Authorization:"Bearer "+s.access_token};}
async function callUpload(file,coll){const h=await headers();const body=new FormData();body.append("file",file);body.append("collection",coll);const res=await fetch(ROOT+"/functions/v1/cf-r2-media",{method:"POST",headers:h,body});const json=await res.json().catch(()=>({}));if(!res.ok)throw Error(json.error||("Error "+res.status+" al subir el archivo"));return json;}
async function callDelete(id){const h=await headers();const res=await fetch(ROOT+"/functions/v1/cf-r2-media",{method:"DELETE",headers:{...h,"Content-Type":"application/json"},body:JSON.stringify({id})});const json=await res.json().catch(()=>({}));if(!res.ok)throw Error(json.error||("Error "+res.status+" al eliminar"));return json;}
async function load(){items=await window.CFAPI.query("cf_media_assets","select=*&order=sort_order.asc,created_at.desc",{auth:true});renderList();}
function renderList(){if(!panel)return;const target=panel.querySelector("#r2-list");if(!target)return;const subset=items.filter(x=>x.collection===collection);target.innerHTML=subset.length?subset.map(x=>`<article class="r2-asset" data-id="${esc(x.id)}"><div class="r2-preview">${x.content_type?.startsWith("image/")?`<img src="${esc(x.public_url)}" alt="" loading="lazy">`:'<span>ARCHIVO</span>'}</div><div class="r2-asset-fields"><label>Título<input class="r2-title" maxlength="160" value="${esc(x.title||"")}"></label><label>Categoría / grupo<input class="r2-category" maxlength="100" value="${esc(x.category||"")}"></label><label>Orden<input class="r2-order" type="number" value="${Number(x.sort_order)||0}"></label><label class="r2-check"><input class="r2-published" type="checkbox" ${x.published?"checked":""}> Publicado</label><div class="r2-url"><a href="${esc(x.public_url)}" target="_blank" rel="noopener noreferrer">Ver archivo</a> · ${esc(x.file_name)}</div><div class="r2-actions"><button data-save="${esc(x.id)}" type="button">Guardar ficha</button><button data-copy="${esc(x.id)}" type="button">Copiar URL</button><button class="danger" data-delete="${esc(x.id)}" type="button">Eliminar</button></div></div></article>`).join(""):'<p class="r2-empty">Aún no hay archivos en esta colección. Selecciona una imagen y súbela para comenzar.</p>';}
function render(){if(panel)panel.remove();panel=document.createElement("section");panel.className="r2-overlay";panel.setAttribute("role","dialog");panel.setAttribute("aria-modal","true");panel.setAttribute("aria-label","Biblioteca Multimedia Cloudflare R2");panel.innerHTML=`<div class="r2-modal"><header class="r2-head"><div><small>ADMINISTRACIÓN · CUBA FELIZ</small><h2>Biblioteca Multimedia</h2><p>Archivos públicos en Cloudflare R2 · media.cubafeliz.com</p></div><button id="r2-close" aria-label="Cerrar" type="button">×</button></header><div class="r2-content"><div class="r2-upload"><label>Colección<select id="r2-collection">${COLLECTIONS.map(([v,n])=>`<option value="${v}" ${v===collection?"selected":""}>${n}</option>`).join("")}</select></label><label>Fotografía o PDF (máx. 8 MB)<input id="r2-file" type="file" accept="image/jpeg,image/png,image/webp,image/gif,application/pdf"></label><button id="r2-upload" type="button">Subir a Cloudflare</button><span id="r2-message" class="r2-message" role="status" aria-live="polite"></span></div><p class="r2-note">Las nuevas imágenes quedan inicialmente sin publicar. Para mostrarlas en una página, copia su URL y úsala en el editor de contenido. El cambio de “Publicado” controla su ficha en la biblioteca, no sustituye automáticamente las galerías actuales.</p><div id="r2-list" class="r2-list"></div></div></div>`;document.body.appendChild(panel);panel.querySelector("#r2-close").onclick=close;panel.addEventListener("click",e=>{if(e.target===panel)close()});panel.querySelector("#r2-collection").onchange=e=>{collection=e.target.value;renderList()};panel.querySelector("#r2-upload").onclick=upload;panel.querySelector("#r2-list").addEventListener("click",clickList);load().catch(e=>msg(e.message,true));}
function close(){panel?.remove();panel=null;}
async function upload(){if(busy)return;const file=panel.querySelector("#r2-file").files[0];if(!file)return msg("Selecciona un archivo primero.",true);if(!["image/jpeg","image/png","image/webp","image/gif","application/pdf"].includes(file.type)||file.size>8*1024*1024||!file.size)return msg("Formato no permitido o archivo superior a 8 MB.",true);const button=panel.querySelector("#r2-upload");busy=true;button.disabled=true;msg("Subiendo a Cloudflare R2...");try{await callUpload(file,collection);panel.querySelector("#r2-file").value="";await load();msg("Archivo almacenado correctamente en Cloudflare R2.");}catch(e){msg(e.message,true)}finally{busy=false;button.disabled=false;}}
async function clickList(e){const b=e.target.closest("button[data-save],button[data-delete],button[data-copy]");if(!b)return;const id=b.dataset.save||b.dataset.delete||b.dataset.copy;const item=items.find(x=>x.id===id);if(!item)return;if(b.dataset.copy){try{await navigator.clipboard.writeText(item.public_url);msg("Enlace copiado.");}catch{msg("No se pudo copiar el enlace.",true)}return;}if(b.dataset.delete&&!confirm("¿Eliminar definitivamente este archivo de Cloudflare y su ficha?"))return;const el=b.closest(".r2-asset");b.disabled=true;try{if(b.dataset.delete){await callDelete(id);await load();msg("Archivo eliminado.");}else{await window.CFAPI.mutate("cf_media_assets","PATCH",{title:el.querySelector(".r2-title").value.trim(),category:el.querySelector(".r2-category").value.trim(),sort_order:Number(el.querySelector(".r2-order").value)||0,published:el.querySelector(".r2-published").checked,updated_at:new Date().toISOString()},"id=eq."+encodeURIComponent(id));await load();msg("Ficha actualizada.");}}catch(err){msg(err.message,true)}finally{b.disabled=false;}}
function install(){if(location.hash!=="#portal"||!window.CFAPI?.getSession?.())return;const sidebar=document.querySelector("#app .sidebar");if(!sidebar||sidebar.querySelector("#r2-open"))return;const lead=sidebar.querySelector("#leadView");if(!lead)return;const button=document.createElement("button");button.id="r2-open";button.className="page-link";button.type="button";button.innerHTML='<span class="page-icon" aria-hidden="true">▧</span><span>Biblioteca Multimedia</span>';lead.insertAdjacentElement("afterend",button);button.onclick=()=>{if(!panel)render()};}
const observer=new MutationObserver(()=>{if(panel&&location.hash!=="#portal")close();install()});observer.observe(document.querySelector("#app"),{childList:true,subtree:true});window.addEventListener("hashchange",()=>{if(location.hash!=="#portal")close();});install();
})();